 INSERT  INTO  KeyResults  (PersonId,  RankNo, querytype)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        select distinct x.* from ((
  SELECT  DISTINCT  p.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         CASE  WHEN  v_lvLastName  is  NOT  NULL  THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 Case  When  (p.LastName  ILIKE    v_lvLastName  ||  '%')  Then  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         When  (p.LastName  ILIKE    LEFT(v_lvLastName,  3)  ||  '%')  Then  0.6                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         When  (p.LastName  ILIKE    LEFT(v_lvLastName,  2)  ||  '%')  Then  0.4                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         When  (p.LastName  ILIKE    LEFT(v_lvLastName,  1)  ||  '%')  Then  0.2                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         Else  0  End                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         ELSE  0  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         +  CASE  WHEN  v_lvFirstName  is  NOT  NULL  THEN  Case  When  (p.FirstName  ILIKE    v_lvFirstName  ||  '%')  Then  1  Else  0  End  ELSE  0  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
