       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)  AS  PrimaryAddress,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  PP.phoneNumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       FROM  PersonPhoneNumber  AS  PP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       WHERE  PP.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PP.PersonPhoneTypeKey  =  'H'  limit  1)  AS  HomePhone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     /*(SELECT  PA.city                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1  )  AS  City,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  PA.zipcode                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)  AS  ZipCode,*/                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                     sr.GenderTypeKey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     --(SELECT  string_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                   --  (SELECT  '/'  ||  RT.TypeDescription                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                     --  FROM  RaceType  AS  RT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                     --  JOIN  PersonRaceTypeMap  AS  PRTM  ON  PRTM.RaceTypeKey  =  RT.RaceTypeKey                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     --                                    --AND  PRTM.PersonId  =  sr.PersonId),','))  AS  Race,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 --                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     (SELECT  TM.LoadNumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
       FROM  UserProfile  UP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       JOIN  TeamMemberAssignment  TMA  ON  TMA.SecurityUsersId  =  UP.SecurityUsersId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  TeamMember  TM  ON  TM.TeamMemberId  =  TMA.TeamMemberId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       WHERE  sr.FirstName  =  UP.FirstName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           AND  sr.LastName  =  UP.LastName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           AND  sr.PersonRoleType  ='DSDSEMP')  AS  LoadNumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
           --'LoadNumber'::character  varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  TE.TeamName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       FROM  UserProfile  UP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       JOIN  TeamMemberAssignment  TMA  ON  TMA.SecurityUsersId  =  UP.SecurityUsersId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  TeamMember  TM  ON  TM.TeamMemberId  =  TMA.TeamMemberId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       JOIN  Team  TE  ON  TE.TeamId  =  TM.TeamId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  sr.FirstName  =  UP.FirstName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           AND  sr.LastName  =  UP.LastName                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
           AND  sr.PersonRoleType  ='DSDSEMP'  )  AS  TeamName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  COALESCE(COUNT(1),0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       FROM  IntakeServiceRequest  ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       join  IntakeSerReqStatusType  ISRST  ON  ISR.IntakeSerReqStatusTypeId  =  ISRST.IntakeSerReqStatusTypeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       Left  join    ServiceRequestSubType  SRST  ON  SRST.ServiceRequestSubTypeId  =  ISR.IntakeServiceRequestClassId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  IntakeServiceRequestActor  ISRA  ON  ISR.IntakeServiceId  =  ISRA.IntakeServiceId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       JOIN  Actor  AC  ON  AC.ActorId  =  ISRA.ActorId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       AND  AC.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       JOIN  Person  PR  ON  PR.PersonId  =  AC.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       WHERE  ISR.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  PR.PersonId  =  sr.PersonId)  AS  Priors,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  COALESCE(COUNT(1),0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       FROM  PersonRelation  PerRel                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       WHERE  PerRel.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
           AND  PerRel.PersonId  =  sr.PersonId)  AS  RelationsCount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
           /*                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
     (SELECT  PR.firstname  ||  '  '  ||  PR.lastname  ||  ':'    ||  PRT.description  as  relation                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       FROM  PersonRelation  PerRel                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       JOIN  Person  PR  ON  PR.PersonId  =  PerRel.PersonRelativeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       --Join  PersonRelationType  PRT  On  PRT.personrelationtypeid  =  PerRel.personrelationtypeid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
           JOIN  relationshiptype  PRT  ON  PRT.relationshiptypekey  =  PerRel.actorrelationshipkey AND prt.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       WHERE  PR.ActiveFlag  =  1  AND  PerRel.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
           AND  PerRel.PersonId  =  sr.PersonId  limit  1)  AS  Relations,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                   */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  ( select json_agg(v) from (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 SELECT  PR.firstname  ||  '  '  ||  PR.lastname as personname,  PRT.description  as  relationtype                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 , CASE WHEN PerRel.relationcategory = 'P' THEN 'Primary'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                         WHEN PerRel.relationcategory = 'S' THEN 'Secondary'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         WHEN PerRel.relationcategory = 'O' THEN 'Other'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                   END AS relationcategory                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
       FROM  PersonRelation  PerRel                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       JOIN  Person  PR  ON  PR.PersonId  =  PerRel.PersonRelativeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       Join  relationshiptype  PRT  On  PRT.relationshiptypekey  =  PerRel.actorrelationshipkey and prt.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       WHERE  PR.ActiveFlag  =  1  AND  PerRel.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
           AND  PerRel.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 ) as v)  AS  Relations,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       (Select  al.firstname  ||  '  '  || ( case when al.lastname is not null then al.lastname else '' end ) from  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       WHERE  al.personid  =  sr.personid   and al.activeflag=1  and 
	       CASE  WHEN  v_lvAlias  is  NOT  NULL  THEN  (lower(al.firstname)  ilike  left(lower(v_lvAlias),  3) ||  '%' or lower(al.lastname)   ilike  left(lower(v_lvAlias),  12)  ||  '%')  ELSE  TRUE  END  
	        limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       )  AS  Alias,sr.assistpid,sr.cjamspid, sr.primarylanguageid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
           sr.secondarylanguageid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           sr.primarydesc as primarylanguage,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
           sr.secondarydesc as secondarylanguage ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       sr.safehavenbabyflag ,
	     sr.racetypekey,
       sr.ethnicgrouptypekey    ,
       sr.querytype
 FROM  SortedResults  AS  sr   
 
  order by
	(
      --  case when coalesc(sortcolumn,null) != null then 
      case 
		sortorder
		when 'asc' then
	      case
			sortcolumn
			when 'firstname' then cast( sr.firstname as character varying)
			when 'lastname' then cast( sr.lastname as character varying)
			when 'middlename' then cast(coalesce(sr.middlename,null) as character varying)
			when 'dob' then sr.DOB :: character varying
	when 'gender' then sr.GenderTypeKey
			when 'ssn' then 
			(SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  i.PersonIdentifierTypeKey  =  'SSN'  limit  1)
			when 'dl' then 
			(SELECT  j.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  j.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  j.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  j.PersonIdentifierTypeKey  =  'DL'  limit  1)
		    when 'priors' then 
		    (SELECT  COALESCE(COUNT(1),0)    :: character varying                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       FROM  IntakeServiceRequest  ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       join  IntakeSerReqStatusType  ISRST  ON  ISR.IntakeSerReqStatusTypeId  =  ISRST.IntakeSerReqStatusTypeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       Left  join    ServiceRequestSubType  SRST  ON  SRST.ServiceRequestSubTypeId  =  ISR.IntakeServiceRequestClassId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  IntakeServiceRequestActor  ISRA  ON  ISR.IntakeServiceId  =  ISRA.IntakeServiceId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       JOIN  Actor  AC  ON  AC.ActorId  =  ISRA.ActorId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       AND  AC.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       JOIN  Person  PR  ON  PR.PersonId  =  AC.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       WHERE  ISR.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  PR.PersonId  =  sr.PersonId)
	        when 'mdmid' then  
	        (SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  i.PersonIdentifierTypeKey  =  'MDM_ID'  limit  1)
        	when 'assistpid' then sr.assistpid
           when 'cjamspid' then sr.cjamspid
            when 'address' then
			(SELECT  CAST(COALESCE(TRIM(PA.address),'') as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
		   
           when 'state' then 
		    (SELECT  CAST(PA.state as character  varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
           
            when 'zipcode' then 
            (SELECT  CAST(COALESCE(TRIM(PA.zipcode),'') as  character  varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
           
		else sr.querytype
		end
		else 
	--sr.querytype 
           ( difference(sr.firstname,coalesce(v_lvFirstName,null)) ::  character varying  
--          ,difference(sr.MiddleName,coalesce(v_lvMiddleName,null)) 
--          ,difference(sr.lastname,coalesce(v_lvLastName,null)
          --)
			)
             end) asc NULLS LAST,
             
             (
             
      case
		sortorder
		when 'desc' then
		case
			sortcolumn
			when 'firstname' then cast( sr.firstname as character varying)
			when 'lastname' then cast( sr.lastname as character varying)
			when 'middlename' then cast(coalesce(sr.middlename,null) as character varying)
			when 'dob' then sr.DOB :: character varying
	when 'gender' then sr.GenderTypeKey
			when 'ssn' then 
			 (SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  i.PersonIdentifierTypeKey  =  'SSN'  limit  1)
			
           when 'dl' then 
			(SELECT  j.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  j.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  j.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  j.PersonIdentifierTypeKey  =  'DL'  limit  1)
		    when 'priors' then 
		    (SELECT  COALESCE(COUNT(1),0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       FROM  IntakeServiceRequest  ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       join  IntakeSerReqStatusType  ISRST  ON  ISR.IntakeSerReqStatusTypeId  =  ISRST.IntakeSerReqStatusTypeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       Left  join    ServiceRequestSubType  SRST  ON  SRST.ServiceRequestSubTypeId  =  ISR.IntakeServiceRequestClassId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  IntakeServiceRequestActor  ISRA  ON  ISR.IntakeServiceId  =  ISRA.IntakeServiceId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       JOIN  Actor  AC  ON  AC.ActorId  =  ISRA.ActorId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       AND  AC.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       JOIN  Person  PR  ON  PR.PersonId  =  AC.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       WHERE  ISR.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  PR.PersonId  =  sr.PersonId) :: character varying
	        when 'mdmid' then  
	        (SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
           AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           AND  i.PersonIdentifierTypeKey  =  'MDM_ID'  limit  1)
        	when 'assistpid' then sr.assistpid
        	when 'cjamspid' then sr.cjamspid        
            when 'address' then
			(SELECT  CAST(COALESCE(TRIM(PA.address),'') as character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
		   
           when 'state' then 
		    (SELECT  CAST(PA.state as character  varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
           
            when 'zipcode' then 
            (SELECT  CAST(COALESCE(TRIM(PA.zipcode),'') as  character  varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       FROM  PersonAddress  AS  PA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       WHERE  PA.PersonId  =  sr.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           AND  PA.PersonAddressId  =  sr.PersonAddressId  limit  1)
           
		else   
	--cast(sr.querytype as character varying)
         (difference(sr.firstname,coalesce(v_lvFirstName,null)) :: character varying) 
          
		
		end
		else cast(sr.querytype as character varying)
             end
             ) desc NULLS LAST 
             
--	else 
--	(     querytype , difference(FR.firstname,coalesce(v_lvFirstName,null))  
--          ,difference(FR.MiddleName,coalesce(v_lvMiddleName,null)) 
--          ,difference(FR.lastname,coalesce(v_lvLastName,null)) 
--     )
--     end 
    -- end
		--else cast( IDAS.reportedarea as character varying) 
 /*GROUP  BY  sr.RankNo,  sr.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 sr.PersonRoleId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 sr.PersonRoleType,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 sr.personrolesubtype,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 sr.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
   sr.MiddleName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
   sr.LastName,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
   sr.DOB,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
   sr.DangerLevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
   sr.personaddressid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   sr.gendertypekey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         sr.dateofdeath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
             sr.suffix,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             sr.prefx,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             sr.deceased,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             sr.socialmediasource                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       --  Order  By  sr.querytype                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
   LIMIT  v_liPageSize  OFFSET  v_pageoffset;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
